// instructionsBlock wraps the contract in the marker block agents read. The
// provenance stamp goes INSIDE the markers on purpose: writeIfNew splices the
// whole block on a later init, so the stamp is REPLACED instead of a second
// line accumulating above it.
export function instructionsBlock(provenance, body) {
  return `${PIEZAS_CONTEXT_START}\n${provenance}\n${body}\n${PIEZAS_CONTEXT_END}\n`;
}

